  const f=await fact(db,a,b.id);if(!['accepted','contested','corrected'].includes(b.status))fail('Invalid review status');if(b.revision!==f.revision)fail('Fact changed; refresh before reviewing.',409);const notes=b.status==='contested'?text(b.notes):(b.notes||'').slice(0,8000),approved=b.status==='corrected'?text(b.correction):b.status==='accepted'?f.claim:null;const rid=id();const results=await db.batch([query(db,'INSERT INTO reviews SELECT ?,id,?,?,?,?,? FROM facts WHERE id=? AND revision=?',rid,b.status,approved||f.claim,notes,a.actor,now(),f.id,b.revision),query(db,'UPDATE facts SET status=?,approved_claim=?,notes=?,duplicate_of=NULL,updated_at=?,revision=revision+1 WHERE id=? AND revision=?',b.status,approved,notes,now(),f.id,b.revision)]);if(!results[1].meta.changes)fail('Fact changed; refresh before reviewing.',409);return json({ok:true})
