const application = {async fetch(r,env){try{let p=new URL(r.url).pathname;if(!env.DB)return json({error:'D1 binding missing'},503);if(p==='/mcp'||p==='/agent/mcp')return await mcp(r,env.DB);if(p.startsWith('/api/inventory/')){if(!r.headers.get('oai-authenticated-user-id'))return json({error:'Unauthorized'},401);if(r.method!=='GET'&&r.headers.get('origin')!==new URL(r.url).origin)return json({error:'Same-origin browser request required'},403);return await inventoryApi(env.DB,r,p)}if(p.startsWith('/api/'))return await api(r,env,p);if(p==='/robots.txt')return new Response('User-agent: *\nDisallow: /');if(p!=='/'&&p!=='/inventory')return new Response('Not found',{status:404});if(!r.headers.get('oai-authenticated-user-id'))return new Response('Administrator sign-in required.',{status:401});return new Response(p==='/inventory'?INVENTORY_HTML:HTML,{headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex, nofollow','content-security-policy':"default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'",'referrer-policy':'no-referrer'}})}catch(e){return json({error:e.status?e.message:'Unexpected server error'},e.status||500)}}};
// Sites identity headers must never be trusted on a standalone Worker.
// Only successful administrator Basic authentication creates an internal identity.
export default {async fetch(request,env){
  const headers=new Headers(request.headers);
  headers.delete('oai-authenticated-user-id');
  headers.delete('oai-authenticated-user-email');
  const path=new URL(request.url).pathname;
  if(path!=='/mcp' && path!=='/agent/mcp' && path!=='/robots.txt'){
    if(!env.ADMIN_PASSWORD || env.ADMIN_PASSWORD.length<20)return json({error:'Administrator secret missing: set ADMIN_PASSWORD (at least 20 characters).'},503);
    let supplied='';
    try{if((headers.get('authorization')||'').startsWith('Basic '))supplied=atob(headers.get('authorization').slice(6))}catch{}
    const expected=(env.ADMIN_USERNAME||'admin')+':'+env.ADMIN_PASSWORD;
    // Hash to equal length, then compare every byte.
    const left=await hash(supplied),right=await hash(expected);
    let mismatch=0;for(let i=0;i<left.length;i++)mismatch|=left.charCodeAt(i)^right.charCodeAt(i);
    if(mismatch)return new Response('Administrator sign-in required.',{status:401,headers:{'WWW-Authenticate':'Basic realm="Fact Ledger", charset="UTF-8"','Cache-Control':'no-store'}});
    headers.set('oai-authenticated-user-id','administrator');
  }
  const response=await application.fetch(new Request(request,{headers}),env);
  response.headers.set('X-Content-Type-Options','nosniff');
  response.headers.set('X-Robots-Tag','noindex, nofollow');
  response.headers.set('Referrer-Policy','no-referrer');
  return response;
}};

