function listNavHtml(){const rows=filteredLists();const selectedList=state.lists.find(l=>l.id===selected);return '<div class="label">PROPERTIES <span class="count">'+state.lists.length+'</span></div><input class="list-search" id="listq" type="search" placeholder="Search properties…" value="'+esc(listQuery)+'" aria-label="Search properties"'+(selectedList?' title="Selected: '+esc(selectedList.name)+'"':'')+'><p class="list-meta">'+(selectedList?'Selected: <b>'+esc(shortListName(selectedList.name))+'</b> · ':'Choose a property · ')+'Showing '+rows.length+(rows.length!==state.lists.length?' of '+state.lists.length:'')+'</p><div class="list-scroll" id="listscroll">'+(rows.length?rows.map(l=>'<button type="button" data-list="'+l.id+'" class="'+(selected===l.id?'selected':'')+'" title="'+esc(l.name)+'">'+esc(shortListName(l.name))+'</button>').join(''):'<p class="muted subtle">No properties match.</p>')+'</div><button id="addlist">＋ New list</button>'}
async function load(){state=await api('state');state.pages=state.pages||[];let saved='';try{saved=localStorage.getItem(LIST_KEY)||''}catch{}if(saved&&state.lists.some(l=>l.id===saved))selected=saved;else if(!state.lists.some(l=>l.id===selected)){selected='';pageFilter=''}render()}
